// Reset forces for the range
for (size_t i = start; i < end; ++i) {
    particles[i].force = glm::vec3(0.0f);
}

// Iterate over each particle in the range and accumulate forces from its neighbors
for (size_t i = start; i < end; ++i) {
    Particle &pi = particles[i];
    // Determine the hash cell of the current particle
    uint16_t cellHash = pi.hash;

    // Scan neighboring cells (including own cell)
    for (int dx = -1; dx <= 1; ++dx) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dz = -1; dz <= 1; ++dz) {
                // Compute neighbor cell hash using the same hash function as on GPU
                // Recreate the cell position from the hash (inverse not needed;
                // we can recompute hash from cell coordinates directly)
                // Since we don't have the original cell coordinates, we approximate
                // by using the particle's position divided by h.
                glm::ivec3 baseCell = {
                    static_cast<int>(pi.position.x / h),
                    static_cast<int>(pi.position.y / h),
                    static_cast<int>(pi.position.z / h)
                };
                glm::ivec3 neighborCell = baseCell + glm::ivec3(dx, dy, dz);
                uint32_t neighborHash = static_cast<uint32_t>(
                    (neighborCell.x * 73856093u) ^
                    (neighborCell.y * 19349663u) ^
                    (neighborCell.z * 83492791u)
                ) % TABLE_SIZE;

                // Look up the first particle index for this hash
                uint32_t pjIndex = particleTable[neighborHash];
                if (pjIndex == NO_PARTICLE) {
                    continue;
                }

                // Iterate over particles sharing the same hash
                for (size_t j = pjIndex; j < particleCount; ++j) {
                    Particle &pj = particles[j];
                    if (pj.hash != neighborHash) break; // end of this bucket
                    if (j == i) continue; // skip self

                    // Compute distance and check interaction radius
                    glm::vec3 r = pj.position - pi.position;
                    float r2 = glm::dot(r, r);
                    if (r2 >= h2) continue;

                    float rLen = std::sqrt(r2);
                    // Avoid division by zero
                    if (rLen < 1e-6f) continue;

                    // Pressure force contribution
                    float pressureTerm = -(pi.pressure + pj.pressure) / (2.0f * pj.density);
                    glm::vec3 pressureForce = pressureTerm * spikyGrad * std::pow(h - rLen, 2) * (r / rLen);

                    // Viscosity force contribution
                    glm::vec3 velDiff = pj.velocity - pi.velocity;
                    float viscosityTerm = viscosity * spikyLap * (h - rLen);
                    glm::vec3 viscosityForce = viscosityTerm * velDiff / pj.density;

                    // Accumulate forces
                    pi.force += pressureForce + viscosityForce;
                }
            }
        }
    }
}

